```javascript
export function buildIndex(documents) {
  const index = new Map();
  for (const doc of documents) {
    const tokens = doc.text.toLowerCase().split(/\W+/);
    for (const token of tokens) {
      if (!token) continue;
      if (!index.has(token)) index.set(token, new Set());
      index.get(token).add(doc.id);
    }
  }
  return index;
}
